11	/**
12	 * Rejects the create when 100 or more owners have already been created on the same business day,
13	 * counted by {@link Owner#getRegistrationDate() registrationDate} equal to this request's effective
14	 * business day. The effective date is the supplied (or defaulted) registration date rolled forward
15	 * off any weekend, matching what {@link BuildOwner} will store. The daily quota is full, so no
16	 * further owner may be created for that day; it is rejected 429 via
17	 * {@link OwnerDailyLimitExceededException}.
18	 *
19	 * <p>Runs before {@link SaveOwner}, so the count reflects only the existing owners, not the
20	 * one being created.
21	 */
22	public class RequireDailyOwnerLimit {
23	
24	    /** At most this many owners may be created on any one business day. */
25	    static final long DAILY_LIMIT = 100;
26	
27	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
28	            throws OwnerDailyLimitExceededException {
29	        LocalDate businessDay = RegistrationDate.effective(request);
30	        long createdThatDay = ownerRepository.findAll().stream()
31	                .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
32	                .count();
33	        if (createdThatDay >= DAILY_LIMIT) {
34	            throw new OwnerDailyLimitExceededException(businessDay, createdThatDay);
35	        }
36	    }
37	}
